  s += `  hero: {\n    title: '${d.ht}',\n    description: '${d.hd}',\n  },\n\n`;
  s += `  marketOverview: '${d.mo}',\n\n`;
  s += '  productIdeas: [\n' + d.pi.map(p=>`    { title: '${p[0]}', description: '${p[1]}', appId: '${p[2]}' },`).join('\n') + '\n  ],\n\n';
